<?php require __DIR__.'/../src/ReleaseService.php';$u=requireLogin();$c=db();$projectId=(int)($_REQUEST['project_id']??0);if(!$projectId){$r=queryParams($c,'SELECT project_id FROM project_members WHERE user_id=$1 ORDER BY project_id LIMIT 1',[(string)$u['id']]);$projectId=(int)(pg_fetch_result($r,0,0)?:0);}if($projectId)requireProjectAccess($c,$projectId,$u);$err='';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$projectId=(int)$_POST['project_id'];requireProjectAccess($c,$projectId,$u);try{$action=(string)$_POST['action'];if($action==='create'){if(!isReleaseManager($c,$projectId,$u))throw new RuntimeException('Chỉ người phụ trách phát hành mới được tạo phiên bản.');queryParams($c,'INSERT INTO releases(project_id,version_name,description,created_by) VALUES($1,$2,$3,$4)',[(string)$projectId,trim((string)$_POST['version_name']),trim((string)$_POST['description']),(string)$u['id']]);$msg='Đã tạo phiên bản.';}elseif($action==='add_item'){if(!isReleaseManager($c,$projectId,$u))throw new RuntimeException('Chỉ người phụ trách phát hành mới được thay đổi danh sách.');$rid=(int)$_POST['release_id'];$iid=(int)$_POST['issue_id'];$r=queryParams($c,"SELECT r.status,i.title,i.status issue_status,i.priority,COALESCE(u.full_name,'') assignee,i.description FROM releases r JOIN issues dummy ON dummy.project_id=r.project_id JOIN issues i ON i.id=$2 LEFT JOIN users u ON u.id=i.assignee_id WHERE r.id=$1 AND r.project_id=$3 AND i.project_id=$3 AND r.status='planned' LIMIT 1",[(string)$rid,(string)$iid,(string)$projectId]);$x=pg_fetch_assoc($r);if(!$x)throw new RuntimeException('Phiên bản đã chốt hoặc công việc không thuộc dự án.');queryParams($c,'INSERT INTO release_items(release_id,issue_id,snapshot_title,snapshot_status,snapshot_priority,snapshot_assignee,snapshot_description) VALUES($1,$2,$3,$4,$5,$6,$7) ON CONFLICT(release_id,issue_id) DO NOTHING',[(string)$rid,(string)$iid,$x['title'],$x['issue_status'],$x['priority'],$x['assignee'],$x['description']]);$msg='Đã thêm công việc vào danh sách dự kiến.';}elseif($action==='check'){$res=ReleaseService::check($c,(int)$_POST['release_id'],$projectId);$msg=$res['problems']?'Chưa đủ điều kiện: '.implode(' | ',$res['problems']):'Kiểm tra đạt: có thể chốt phiên bản.';}elseif($action==='release'){if(!isReleaseManager($c,$projectId,$u))throw new RuntimeException('Chỉ người phụ trách phát hành mới được chốt phiên bản.');$rid=(int)$_POST['release_id'];ReleaseService::snapshot($c,$rid,$projectId,(int)$u['id']);$msg='Đã chốt phiên bản. Snapshot không thay đổi khi công việc tiếp tục được sửa.';}}catch(Throwable $e){$err=$e->getMessage();}}
$projects=pg_fetch_all(queryParams($c,'SELECT p.id,p.name FROM projects p JOIN project_members pm ON pm.project_id=p.id WHERE pm.user_id=$1 ORDER BY p.id',[(string)$u['id']]))?:[];$rels=pg_fetch_all(queryParams($c,'SELECT r.*,p.name project_name,(SELECT count(*) FROM release_items ri WHERE ri.release_id=r.id) item_count FROM releases r JOIN projects p ON p.id=r.project_id JOIN project_members pm ON pm.project_id=p.id AND pm.user_id=$2 WHERE r.project_id=$1 ORDER BY r.id',[(string)$projectId,(string)$u['id']]))?:[];$issues=pg_fetch_all(queryParams($c,'SELECT id,title,priority,status FROM issues WHERE project_id=$1 ORDER BY id',[(string)$projectId]))?:[];$selected=(int)($_GET['id']??$_POST['release_id']??0);$items=[];$check=null;if($selected){$r=queryParams($c,'SELECT * FROM releases WHERE id=$1 AND project_id=$2',[(string)$selected,(string)$projectId]);if(pg_num_rows($r)){$check=ReleaseService::check($c,$selected,$projectId);$items=pg_fetch_all(queryParams($c,'SELECT * FROM release_items WHERE release_id=$1 ORDER BY id',[(string)$selected]))?:[];}}
pageStart('Phiên bản phát hành');if($err)echo '<p class="error">'.nl2br(h($err)).'</p>';if($msg)echo '<p class="ok">'.h($msg).'</p>';?><section class="panel"><form method="get"><label class="field">Dự án<select name="project_id" onchange="this.form.submit()"><?php foreach($projects as $p):?><option value="<?=$p['id']?>" <?=$projectId==(int)$p['id']?'selected':''?>><?=h($p['name'])?></option><?php endforeach;?></select></label></form></section><?php if(isReleaseManager($c,$projectId,$u)):?><section class="panel"><h2>Lập phiên bản dự kiến</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrfToken())?>"><input type="hidden" name="action" value="create"><input type="hidden" name="project_id" value="<?=$projectId?>"><label class="field">Tên phiên bản<input name="version_name" placeholder="1.2.0" required></label><label class="field">Mô tả<textarea name="description"></textarea></label><button>Tạo phiên bản</button></form></section><?php endif;?><section class="panel"><h2>Các phiên bản</h2><div class="table-wrap"><table><thead><tr><th>Phiên bản</th><th>Trạng thái</th><th>Số mục</th><th></th></tr></thead><tbody><?php foreach($rels as $r):?><tr><td><?=h($r['version_name'])?> — <?=h($r['description'])?></td><td><span class="pill"><?=h($r['status'])?></span></td><td><?=$r['item_count']?></td><td><a href="?project_id=<?=$projectId?>&id=<?=$r['id']?>">Chi tiết</a> · <a href="/release-notes.php?id=<?=$r['id']?>">Ghi chú</a></td></tr><?php endforeach;?></tbody></table></div></section><?php if($check):?><section class="panel"><h2>Chi tiết <?=h($check['release']['version_name'])?></h2><h3>Danh sách snapshot</h3><?php if(!$items):?><p>Chưa gắn công việc.</p><?php else:?><ul><?php foreach($items as $i):?><li>#<?=$i['issue_id']?> <?=h($i['snapshot_title'])?> · <?=h($i['snapshot_priority'])?> · <?=h($i['snapshot_status'])?></li><?php endforeach;?></ul><?php endif;?><?php if($check['problems']):?><div class="error"><b>Chưa đủ điều kiện:</b><ul><?php foreach($check['problems'] as $p):?><li><?=h($p)?></li><?php endforeach;?></ul></div><?php else:?><p class="ok">Điều kiện phát hành đạt.</p><?php endif;?><?php if($check['release']['status']==='planned'):?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=h(csrfToken())?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><input type="hidden" name="release_id" value="<?=$selected?>"><button name="action" value="check">Kiểm tra điều kiện</button></form><?php if(isReleaseManager($c,$projectId,$u)):?><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=h(csrfToken())?>"><input type="hidden" name="project_id" value="<?=$projectId?>"><input type="hidden" name="release_id" value="<?=$selected?>"><button name="action" value="release">Chốt phát hành</button></form><form method="post"><input type="hidden" name="csrf" value="<?=h(csrfToken())?>"><input type="hidden" name="action" value="add_item"><input type="hidden" name="project_id" value="<?=$projectId?>"><input type="hidden" name="release_id" value="<?=$selected?>"><label class="field">Thêm công việc<select name="issue_id"><?php foreach($issues as $i):?><option value="<?=$i['id']?>">#<?=$i['id']?> · <?=h($i['title'])?> (<?=h($i['priority'])?> / <?=h($i['status'])?>)</option><?php endforeach;?></select></label><button>Thêm vào phiên bản</button></form><?php endif;?><?php endif;?></section><?php endif;?><?php pageEnd(); ?>